create or replace function public.recompute_durability_scores(min_sample integer default 5) returns integer language plpgsql volatile security definer set search_path = public as $$ declare touched integer := 0; begin drop table if exists best_scores; create temp table best_scores on commit drop as with windows as (select unnest(array[12, 6, 3]) as months), eligible as ( select l.website_id, w.months, count(*) filter ( where l.lost_at is null or l.lost_at >= l.published_at + make_interval(months => w.months) ) as survived, count(*) as sample from public.monitored_links l cross join windows w where l.published_at <= timezone('utc', now()) - make_interval(months => w.months) group by l.website_id, w.months ) select distinct on (website_id) website_id, months, survived, sample from eligible where sample >= greatest(1, min_sample) order by website_id, months desc; update public.websites s set durability_pct = round((b.survived::numeric / b.sample) * 100), durability_sample = b.sample, durability_window_months = b.months, durability_updated_at = timezone('utc', now()) from best_scores b where s.id = b.website_id; get diagnostics touched = row_count; update public.websites s set durability_pct = null, durability_sample = 0, durability_window_months = null, durability_updated_at = timezone('utc', now()) where s.durability_pct is not null and not exists (select 1 from best_scores b where b.website_id = s.id); return touched; end; $$;
